 static LineRenderer Trace(string n,Transform parent,Material m){var o=new GameObject(n,typeof(LineRenderer));o.transform.SetParent(parent,false);var l=o.GetComponent<LineRenderer>();o.transform.localScale=new Vector3(1/parent.lossyScale.x,1/parent.lossyScale.y,1/parent.lossyScale.z);l.useWorldSpace=false;l.widthMultiplier=.018f;string materialPath=Root+"Materials/"+n+" trace.mat";var lineMat=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(!lineMat){lineMat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));lineMat.color=n.StartsWith("Input")?new Color(.1f,.8f,.9f):new Color(1,.65f,.2f);AssetDatabase.CreateAsset(lineMat,materialPath);}l.sharedMaterial=lineMat;return l;}
