 public static void Validate(){var games=UnityEngine.Object.FindObjectsByType<VillageGame>(FindObjectsSortMode.None);if(games.Length!=1)throw new Exception("Expected one game root");var g=games[0];if(g.transitions){SeparateHouseBuilder.Validate();return;}if(!g.player||!g.ui||!g.hardware||!g.villageSpawn||g.interiors.Length!=6||g.entrances.Length!=6)throw new Exception("Scene wiring incomplete");if(UnityEngine.Object.FindObjectsByType<EngineeringStation>(FindObjectsSortMode.None).Length!=5)throw new Exception("Expected five stations");int missing=0;foreach(var go in SceneManager.GetActiveScene().GetRootGameObjects())foreach(var tr in go.GetComponentsInChildren<Transform>(true))missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(tr.gameObject);File.WriteAllText("Verification/scene-validation.txt","Game roots: 1\nInteriors: 6\nStations: 5\nMissing scripts: "+missing+"\nScene references validated\n");if(missing>0)throw new Exception("Missing scripts: "+missing);}
